-- Historical Preview SQL, read from migration record. Offline reconstruction only.
-- Synthetic business seed inserts removed; do not apply this to hosted databases.
create or replace view admin.my_profile with (security_invoker=true, security_barrier=true) as select auth_user_id, display_name, status, is_owner, created_at, last_login_at from admin.admin_profiles;
create or replace view admin.admin_profile_directory with (security_invoker=true, security_barrier=true) as select auth_user_id, display_name, status, is_owner from admin.admin_profiles;
create or replace view admin.my_sessions with (security_invoker=true, security_barrier=true) as select session_id, created_at, last_seen_at, user_agent, revoked_at from admin.admin_session_registry;
grant select on admin.my_profile, admin.admin_profile_directory, admin.my_sessions to authenticated;
create or replace function admin.claim_first_owner(p_display_name text) returns uuid language plpgsql security definer set search_path='' as $$
declare v_uid uuid := auth.uid(); v_email text := lower(coalesce(auth.jwt()->>'email','')); v_inv admin.admin_invitations; v_now timestamptz := now();
begin
 if v_uid is null then raise exception 'unauthenticated'; end if;
 if coalesce(auth.jwt()->>'aal','aal1') <> 'aal2' then raise exception 'aal2_required'; end if;
 if not exists (select 1 from auth.mfa_factors f where f.user_id=v_uid and f.factor_type='totp' and f.status='verified') then raise exception 'verified_totp_required'; end if;
 perform 1 from admin.admin_bootstrap_state where id=true for update;
 if exists (select 1 from admin.admin_bootstrap_state where id=true and owner_claimed_at is not null) then raise exception 'bootstrap_locked'; end if;
 select * into v_inv from admin.admin_invitations where invitation_kind='bootstrap' and status='pending' and expires_at>v_now and lower(email)=v_email order by created_at limit 1 for update;
 if not found then raise exception 'bootstrap_invitation_not_found'; end if;
 insert into admin.identity_operations(operation_type,idempotency_key,invitation_id,auth_user_id,actor_auth_user_id,state,payload_summary) values ('bootstrap_claim','bootstrap:'||v_inv.id, v_inv.id, v_uid, v_uid, 'db_done', jsonb_build_object('invitation_validated_at',v_now,'auth_identity_validated_at',v_now,'mfa_validated_at',v_now)) on conflict (idempotency_key) do update set state='db_done', attempts=admin.identity_operations.attempts+1, updated_at=v_now;
 update admin.admin_invitations set status='accepted', accepted_at=v_now, accepted_auth_user_id=v_uid, updated_at=v_now where id=v_inv.id and status='pending';
 if not found then raise exception 'invitation_consumed'; end if;
 insert into admin.admin_profiles(auth_user_id,display_name,email_snapshot,status,is_owner,invitation_id,invitation_kind) values (v_uid, p_display_name, v_email, 'invited', true, v_inv.id, 'bootstrap');
 insert into admin.admin_role_assignments(auth_user_id,role_key) values (v_uid,'super_admin');
 update admin.admin_bootstrap_state set owner_claimed_at=v_now, owner_auth_user_id=v_uid, bootstrap_disabled_at=v_now, updated_at=v_now where id=true and owner_claimed_at is null;
 if not found then raise exception 'bootstrap_race_lost'; end if;
 update admin.admin_profiles set status='active', updated_at=v_now where auth_user_id=v_uid;
 insert into admin.admin_session_registry(session_id,auth_user_id,aal_at_issue) values ((auth.jwt()->>'session_id')::uuid, v_uid, 'aal2') on conflict (session_id) do update set revoked_at=null;
 insert into admin.admin_mfa_status(auth_user_id,totp_verified_factor_count,has_verified_totp,last_factor_verified_at,last_synced_at,enrollment_required) values (v_uid,1,true,v_now,v_now,false) on conflict (auth_user_id) do update set totp_verified_factor_count=1,has_verified_totp=true,last_synced_at=v_now,enrollment_required=false;
 update admin.identity_operations set state='completed', completed_at=v_now, updated_at=v_now where idempotency_key='bootstrap:'||v_inv.id;
 perform audit.append_audit(v_uid,'owner.claimed','admin_bootstrap_state','true','success', jsonb_build_object('owner',v_uid));
 return v_uid;
end $$;
revoke execute on function admin.claim_first_owner(text) from public, anon, service_role;
grant execute on function admin.claim_first_owner(text) to authenticated;
create table preview.preview_creators (id uuid primary key default gen_random_uuid(), display_name text not null, handle citext not null unique, niche text, status text not null default 'active' check (status in ('active','flagged','suspended')), follower_band text, is_synthetic boolean not null default true check (is_synthetic), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table preview.preview_brands (id uuid primary key default gen_random_uuid(), name text not null, industry text, status text not null default 'active', is_synthetic boolean not null default true check (is_synthetic), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table preview.preview_users (id uuid primary key default gen_random_uuid(), display_name text not null, email citext not null unique, status text not null default 'active', is_synthetic boolean not null default true check (is_synthetic), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table preview.preview_campaigns (id uuid primary key default gen_random_uuid(), brand_id uuid not null references preview.preview_brands(id) on delete restrict, title text not null, status text not null default 'draft' check (status in ('draft','live','paused','ended')), budget_band text, starts_on date, ends_on date, is_synthetic boolean not null default true check (is_synthetic), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table preview.preview_campaign_applications (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references preview.preview_campaigns(id) on delete restrict, creator_id uuid references preview.preview_creators(id) on delete restrict, user_id uuid references preview.preview_users(id) on delete restrict, status text not null default 'applied' check (status in ('applied','shortlisted','rejected','accepted')), is_synthetic boolean not null default true check (is_synthetic), created_at timestamptz not null default now(), check ((creator_id is not null) <> (user_id is not null)));
create unique index campaign_applications_creator on preview.preview_campaign_applications (campaign_id, creator_id) where creator_id is not null;
create table preview.preview_reports (id uuid primary key default gen_random_uuid(), reporter_user_id uuid references preview.preview_users(id) on delete restrict, subject_creator_id uuid references preview.preview_creators(id) on delete restrict, subject_campaign_id uuid references preview.preview_campaigns(id) on delete restrict, subject_user_id uuid references preview.preview_users(id) on delete restrict, reason text not null, status text not null default 'open' check (status in ('open','reviewing','resolved','dismissed')), is_synthetic boolean not null default true check (is_synthetic), created_at timestamptz not null default now(), check ((subject_creator_id is not null)::int + (subject_campaign_id is not null)::int + (subject_user_id is not null)::int = 1));
create table preview.moderation_actions (id uuid primary key default gen_random_uuid(), report_id uuid not null references preview.preview_reports(id) on delete restrict, admin_id uuid not null references admin.admin_profiles(auth_user_id) on delete restrict, action text not null, note text, created_at timestamptz not null default now());
create table ops.ops_site_config (key text primary key, value jsonb not null, updated_by uuid references admin.admin_profiles(auth_user_id) on delete restrict, updated_at timestamptz not null default now());
create table preview.analytics_daily_rollups (day date not null, metric text not null, campaign_id uuid references preview.preview_campaigns(id) on delete restrict, value numeric not null default 0, primary key (day, metric, campaign_id));
create table ops.ops_notifications (id uuid primary key default gen_random_uuid(), recipient_admin_id uuid references admin.admin_profiles(auth_user_id) on delete restrict, channel text not null, template_key text not null, payload jsonb not null default '{}'::jsonb, status text not null default 'queued', sent_at timestamptz, created_at timestamptz not null default now());
create table preview.crm_contacts (id uuid primary key default gen_random_uuid(), name text not null, company text, email citext, stage text not null default 'lead', is_synthetic boolean not null default true check (is_synthetic), created_at timestamptz not null default now());
create table preview.crm_interactions (id uuid primary key default gen_random_uuid(), contact_id uuid not null references preview.crm_contacts(id) on delete restrict, admin_id uuid references admin.admin_profiles(auth_user_id) on delete restrict, kind text not null, note text, created_at timestamptz not null default now());
create table preview.privacy_requests (id uuid primary key default gen_random_uuid(), requester_email citext not null, request_type text not null check (request_type in ('access','export','deletion','correction')), status text not null default 'open', handled_by uuid references admin.admin_profiles(auth_user_id) on delete restrict, due_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table ops.ops_backup_records (id uuid primary key default gen_random_uuid(), backup_type text not null, scope text not null, status text not null, location_label text not null, size_bytes bigint, checksum text, started_at timestamptz, finished_at timestamptz, recorded_by uuid references admin.admin_profiles(auth_user_id) on delete restrict, restore_tested_at timestamptz, notes text, created_at timestamptz not null default now());
alter table preview.preview_creators enable row level security; alter table preview.preview_brands enable row level security; alter table preview.preview_users enable row level security; alter table preview.preview_campaigns enable row level security; alter table preview.preview_campaign_applications enable row level security; alter table preview.preview_reports enable row level security; alter table preview.moderation_actions enable row level security; alter table ops.ops_site_config enable row level security; alter table preview.analytics_daily_rollups enable row level security; alter table ops.ops_notifications enable row level security; alter table preview.crm_contacts enable row level security; alter table preview.crm_interactions enable row level security; alter table preview.privacy_requests enable row level security; alter table ops.ops_backup_records enable row level security;
revoke all on preview.preview_creators, preview.preview_brands, preview.preview_users, preview.preview_campaigns, preview.preview_campaign_applications, preview.preview_reports, preview.moderation_actions, ops.ops_site_config, preview.analytics_daily_rollups, ops.ops_notifications, preview.crm_contacts, preview.crm_interactions, preview.privacy_requests, ops.ops_backup_records from anon, authenticated;
grant select, insert, update on preview.preview_creators, preview.preview_brands, preview.preview_users, preview.preview_campaigns, preview.preview_campaign_applications, preview.preview_reports, preview.moderation_actions, ops.ops_site_config, preview.analytics_daily_rollups, ops.ops_notifications, preview.crm_contacts, preview.crm_interactions, preview.privacy_requests, ops.ops_backup_records to authenticated;
create policy creators_rw on preview.preview_creators for all to authenticated using (admin.has_permission('creators.read')) with check (admin.has_permission('creators.manage'));
create policy brands_rw on preview.preview_brands for all to authenticated using (admin.has_permission('brands.read')) with check (admin.has_permission('brands.manage'));
create policy users_rw on preview.preview_users for all to authenticated using (admin.has_permission('users.read')) with check (admin.has_permission('users.manage'));
create policy campaigns_rw on preview.preview_campaigns for all to authenticated using (admin.has_permission('campaigns.read')) with check (admin.has_permission('campaigns.manage'));
create policy applications_rw on preview.preview_campaign_applications for all to authenticated using (admin.has_permission('campaigns.read')) with check (admin.has_permission('campaigns.manage'));
create policy reports_rw on preview.preview_reports for all to authenticated using (admin.has_permission('moderation.read')) with check (admin.has_permission('moderation.act'));
create policy moderation_rw on preview.moderation_actions for all to authenticated using (admin.has_permission('moderation.read')) with check (admin.has_permission('moderation.act'));
create policy site_config_rw on ops.ops_site_config for all to authenticated using (admin.has_permission('site_config.read')) with check (admin.has_permission('site_config.manage'));
create policy analytics_read on preview.analytics_daily_rollups for select to authenticated using (admin.has_permission('analytics.read'));
create policy notifications_rw on ops.ops_notifications for all to authenticated using (admin.has_permission('notifications.manage')) with check (admin.has_permission('notifications.manage'));
create policy crm_rw on preview.crm_contacts for all to authenticated using (admin.has_permission('crm.read')) with check (admin.has_permission('crm.manage'));
create policy crm_interactions_rw on preview.crm_interactions for all to authenticated using (admin.has_permission('crm.read')) with check (admin.has_permission('crm.manage'));
create policy privacy_rw on preview.privacy_requests for all to authenticated using (admin.has_permission('privacy.read')) with check (admin.has_permission('privacy.manage'));
create policy backups_read on ops.ops_backup_records for select to authenticated using (admin.has_permission('backups.read'));
